# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe TimekeepingHandoffFakes::InMemoryTimekeepingStore do
  def handoff_fakes_entry_row(id:, version:)
    at = Time.utc(2026, 1, 5, 9)
    values = {
      "id" => id, "company_id" => 1, "version" => version, "project_id" => 10, "user_id" => 20,
      "work_date" => Date.new(2026, 1, 5), "duration" => 60.0, "note" => "", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "proof_metadata" => {}, "created_at" => at, "updated_at" => at
    }
    Timekeeping::Handoff::Checkpoint::TABLES.fetch("entries").index_with { |column| values[column] }
  end

  # A checkpoint holding the given entries, with every other table empty.
  def handoff_fakes_checkpoint(*entries)
    tables = Timekeeping::Handoff::Checkpoint::TABLES.keys.index_with { [] }
    Timekeeping::Handoff::Checkpoint.build(tables: tables.merge("entries" => entries))
  end

  # "The less faithful copies can pass where the real store would refuse"
  # Legacy rows sit at version 0; a runner that forgot to raise them to the
  # lowest loadable version must be stopped here, not by the real service only.
  it "refuses a checkpoint whose entry version is 0, nil or a String and leaves the empty store empty" do
    store = described_class.new
    before = store.export_checkpoint.digest

    [0, nil, "1"].each do |version|
      expect { store.load_checkpoint(handoff_fakes_checkpoint(handoff_fakes_entry_row(id: 7, version:))) }
        .to raise_error(Timekeeping::Handoff::Store::Error)
    end

    expect(store.rows.fetch("entries")).to eq([])
    expect(store.export_checkpoint).not_to be_nil
    expect(store.export_checkpoint.digest).to eq(before)
  end

  it "refuses a checkpoint holding an entry below version 1 or not an Integer and keeps the rows it held" do
    store = described_class.new
    store.load_checkpoint(handoff_fakes_checkpoint(handoff_fakes_entry_row(id: 7, version: 2)))

    expect { store.load_checkpoint(handoff_fakes_checkpoint(handoff_fakes_entry_row(id: 8, version: 0))) }
      .to raise_error(Timekeeping::Handoff::Store::Error)
    expect { store.load_checkpoint(handoff_fakes_checkpoint(handoff_fakes_entry_row(id: 7, version: 0))) }
      .to raise_error(Timekeeping::Handoff::Store::Error)
    expect { store.load_checkpoint(handoff_fakes_checkpoint(handoff_fakes_entry_row(id: 7, version: "3"))) }
      .to raise_error(Timekeeping::Handoff::Store::Error)

    expect(store.rows.fetch("entries").pluck("id", "version")).to eq([[7, 2]])
  end

  # A checkpoint re-sent after Timekeeping already holds a newer version must be
  # refused, and the refusal must not half-apply the older rows.
  it "refuses to replace a stored entry with an older version and reloads the same version" do
    store = described_class.new
    store.load_checkpoint(handoff_fakes_checkpoint(handoff_fakes_entry_row(id: 1, version: 3)))

    expect { store.load_checkpoint(handoff_fakes_checkpoint(handoff_fakes_entry_row(id: 1, version: 2))) }
      .to raise_error(Timekeeping::Handoff::Store::Error)
    expect(store.rows.fetch("entries").pluck("version")).to eq([3])
    expect(store.export_checkpoint.rows.fetch("entries").pluck("version")).to eq([3])

    # The same version again is not older, so a resumed load of it is accepted.
    same = handoff_fakes_checkpoint(handoff_fakes_entry_row(id: 1, version: 3))
    expect { store.load_checkpoint(same) }.not_to raise_error
    expect(store.export_checkpoint.digest).to eq(same.digest)
  end

  # The service replaces the earlier correction of an entry rather than adding a
  # second one, so corrections keeps one per entry. That replacement hides a
  # duplicated write, so correction_writes keeps every snapshot as sent.
  it "a second correction of the same entry replaces the first and raises the stored entry version" do
    store = described_class.new
    store.load_checkpoint(handoff_fakes_checkpoint(handoff_fakes_entry_row(id: 5, version: 1)))

    first = store.write_correction_snapshots(snapshots: [{ "id" => 5, "note" => "first" }], version: 2, generation: 2)
    second = store.write_correction_snapshots(snapshots: [{ "id" => 5, "note" => "second" }], version: 3, generation: 3)

    expect([first, second]).to eq([1, 1])
    expect(store.corrections).to eq([{ "id" => 5, "note" => "second", "version" => 3, "generation" => 3 }])
    expect(described_class.entry_id_of(store.corrections.first)).to eq(5)
    expect(store.correction_writes.pluck("note")).to eq(%w[first second])
    expect(store.rows.fetch("entries").first["version"]).to eq(3)
  end

  it "replaces an earlier correction of an entry the store does not hold" do
    store = described_class.new
    snapshot = { "id" => 42, "note" => "corrected" }

    store.write_correction_snapshots(snapshots: [snapshot], version: 1, generation: 2)
    store.write_correction_snapshots(snapshots: [snapshot], version: 2, generation: 3)

    expect(store.corrections).to eq([{ "id" => 42, "note" => "corrected", "version" => 2, "generation" => 3 }])
  end

  it "a new store exports an empty checkpoint, records tagged admission calls and only raises its id sequence" do
    log = []
    store = described_class.new(log:, tag: :timekeeping)

    # The runner reads export_checkpoint before the first load, so it must be an empty checkpoint, never nil.
    exported = store.export_checkpoint
    expect(exported).to be_a(Timekeeping::Handoff::Checkpoint)
    expect(exported.rows.values).to all(be_empty)

    expect(store.enforces_fence?).to be(true)
    expect(store.fence_admission).to be_nil
    expect(store.admit(generation: 2)).to be_nil
    expect(store.calls).to eq([[:fence], [:admit, 2]])
    expect(log).to eq([[:timekeeping, :fence], [:timekeeping, :admit, 2]])

    expect(store.advance_entry_id_sequence(above: 10)).to eq(11)
    expect(store.advance_entry_id_sequence(above: 4)).to eq(11)
    expect(store.highest_outbox_position).to eq(0)
  end
end

RSpec.describe TimekeepingHandoffFakes::RecordingAdmission do
  it "records fence and admit calls itself and appends them to a shared log under its tag" do
    log = [[:settle, 3]]
    tagged = described_class.new(log:, tag: :monolith)
    untagged_log = []
    untagged = described_class.new(log: untagged_log)
    plain = described_class.new

    expect(plain.calls).to be_empty
    expect(tagged.fence_admission).to be_nil
    expect(tagged.admit(generation: 3)).to be_nil
    untagged.admit(generation: 4)
    plain.fence_admission

    expect(tagged.calls).to eq([[:fence], [:admit, 3]])
    # Other records already in the log keep their place; admission calls are appended in order.
    expect(log).to eq([[:settle, 3], [:monolith, :fence], [:monolith, :admit, 3]])
    expect(untagged_log).to eq([[:admit, 4]])
    expect(plain.calls).to eq([[:fence]])
    expect(plain.enforces_fence?).to be(true)
    expect(described_class.new(enforces_fence: false).enforces_fence?).to be(false)
  end

  # The runner specs check that the outgoing owner is fenced before the
  # incoming one is admitted by reading one shared log; each admission must
  # write there in call order, tagged with its owner, and still keep its own
  # untagged record so a "this admission was never called" check can fail.
  it "two tagged admissions sharing one log keep the call order across owners and their own untagged calls" do
    log = []
    monolith = described_class.new(log:, tag: :monolith)
    timekeeping = TimekeepingHandoffFakes::InMemoryTimekeepingStore.new(log:, tag: :timekeeping)
    untouched = described_class.new(log:, tag: :monolith)

    monolith.fence_admission
    timekeeping.admit(generation: 2)
    monolith.admit(generation: 3)

    expect(log).to eq([[:monolith, :fence], [:timekeeping, :admit, 2], [:monolith, :admit, 3]])
    expect(monolith.calls).to eq([[:fence], [:admit, 3]])
    expect(timekeeping.calls).to eq([[:admit, 2]])
    expect(untouched.calls).to be_empty
  end
end

RSpec.describe TimekeepingHandoffFakes, ".owners" do
  it "defaults to the store as Timekeeping's admission, a recording monolith admission, no-op settle and relay drains" do
    timekeeping = TimekeepingHandoffFakes::InMemoryTimekeepingStore.new
    owners = described_class.owners(timekeeping:)
    monolith = owners.fetch(:monolith)

    expect(owners.keys).to contain_exactly(:monolith, :timekeeping)
    expect(owners.fetch(:timekeeping).store).to equal(timekeeping)
    expect(owners.fetch(:timekeeping).admission).to equal(timekeeping)
    expect(monolith.store).to be_a(Timekeeping::Handoff::MonolithStore)
    expect(monolith.admission).to be_a(TimekeepingHandoffFakes::RecordingAdmission)
    expect(monolith.admission.enforces_fence?).to be(true)
    owners.each_value do |owner|
      expect(owner.settle).to be_a(TimekeepingHandoffFakes::NoOpSettle)
      expect(owner.settle.settled?).to be(true)
      expect(owner.drain).to be_a(TimekeepingHandoffFakeRelay)
    end
  end

  it "takes injected admissions and stores, a nil settle, and no drains when relay is false" do
    placeholder = Object.new
    monolith_admission = TimekeepingHandoffFakes::RecordingAdmission.new
    timekeeping_admission = TimekeepingHandoffFakes::RecordingAdmission.new
    owners = described_class.owners(
      timekeeping: placeholder, timekeeping_admission:, monolith_admission:, monolith_store: placeholder,
      settle: nil, relay: false
    )

    expect(owners.fetch(:monolith).admission).to equal(monolith_admission)
    expect(owners.fetch(:timekeeping).admission).to equal(timekeeping_admission)
    expect(owners.values.map(&:store)).to all(equal(placeholder))
    expect(owners.values.map(&:settle)).to eq([nil, nil])
    expect(owners.values.map(&:drain)).to eq([nil, nil])
    # Building owners must not call the injected admissions.
    expect(monolith_admission.calls).to be_empty
    expect(timekeeping_admission.calls).to be_empty

    unadmitted = described_class.owners(timekeeping: placeholder, monolith_admission: nil, relay: false)
    expect(unadmitted.fetch(:monolith).admission).to be_nil
  end
end
